export const RENDER_PACKAGE_PILOTS = Object.freeze(PILOTS.map((entry) => Object.freeze(entry)));

const BY_SOURCE_URL = new Map(RENDER_PACKAGE_PILOTS.map((entry) => [entry.sourceUrl, entry]));
const BY_ASSET_ID = new Map(RENDER_PACKAGE_PILOTS.map((entry) => [entry.assetId, entry]));

export function renderPackagePilotForSourceUrl(url) {
  const clean = String(url || '').replace(/\\/g, '/').split(/[?#]/, 1)[0].replace(/^\.\//, '');
  return BY_SOURCE_URL.get(clean) || null;
}

export function renderPackagePilotForAssetId(assetId) {
  return BY_ASSET_ID.get(String(assetId || '')) || null;
}
